using System.Net;using System.Net.Http.Json;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc.Testing;using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.DependencyInjection.Extensions;using SupportAgent.Core.ExternalData;using SupportAgent.Infrastructure.Identity;
namespace SupportAgent.Tests;

public class Phase14CsrfIntegrationTests:IClassFixture<Phase8ApplicationFactory>
{
 readonly Phase8ApplicationFactory factory;public Phase14CsrfIntegrationTests(Phase8ApplicationFactory factory)=>this.factory=factory;
 [Fact]public async Task Data_source_create_requires_csrf_and_succeeds_with_valid_token(){using var client=await Admin();var rejected=await client.PostAsJsonAsync("/api/admin/data-sources",new{name="Rejected",secretKey="ERP_TEST",enabled=true});Assert.Equal(HttpStatusCode.BadRequest,rejected.StatusCode);var token=await Csrf(client);var accepted=await Post(client,"/api/admin/data-sources",new{name="ERP",secretKey="ERP_TEST",description="Test",enabled=true},token);Assert.Equal(HttpStatusCode.Created,accepted.StatusCode);var list=await client.GetFromJsonAsync<List<ExternalDataSourceSummary>>("/api/admin/data-sources/");Assert.Contains(list!,x=>x.Name=="ERP");}
 [Fact]public async Task Connection_string_is_rejected_instead_of_persisted_as_secret_key(){using var client=await Admin();var token=await Csrf(client);var response=await Post(client,"/api/admin/data-sources",new{name="Unsafe",secretKey="Server=db;Database=erp;User Id=user;Password=secret",enabled=true},token);Assert.Equal(HttpStatusCode.BadRequest,response.StatusCode);Assert.Contains("configuration reference",await response.Content.ReadAsStringAsync(),StringComparison.OrdinalIgnoreCase);var list=await client.GetFromJsonAsync<List<ExternalDataSourceSummary>>("/api/admin/data-sources/");Assert.DoesNotContain(list!,x=>x.Name=="Unsafe");}
 [Fact]public async Task Mapping_mutation_succeeds_with_valid_csrf(){await using var configured=factory.WithWebHostBuilder(b=>b.ConfigureServices(s=>{s.RemoveAll<IExternalSchemaDiscoveryService>();s.AddScoped<IExternalSchemaDiscoveryService,FakeDiscovery>();}));using var client=await Admin(configured);var token=await Csrf(client);var created=await Post(client,"/api/admin/data-sources",new{name="Mapped ERP",secretKey="ERP_TEST",enabled=true},token);var id=(await created.Content.ReadFromJsonAsync<Created>())!.Id;var mapping=new{schema="dbo",table="erp_customer",objectType="BASE TABLE",businessEntityName="Customers",displayName="Customers",description="Customer master",concepts="customer",enabled=true,fields=new[]{new{externalColumnName="customer_code",businessFieldName="CustomerCode",displayName="Customer code",description="Code",dataType="String",concepts="customer code",isQueryable=true,isSensitive=false}}};Assert.Equal(HttpStatusCode.OK,(await Post(client,$"/api/admin/data-sources/{id}/mappings",mapping,token)).StatusCode);Assert.Equal(HttpStatusCode.OK,(await Post(client,$"/api/admin/data-sources/{id}/mappings",mapping,token)).StatusCode);var saved=await client.GetAsync($"/api/admin/data-sources/{id}/mappings");Assert.Equal(HttpStatusCode.OK,saved.StatusCode);Assert.Contains("CustomerCode",await saved.Content.ReadAsStringAsync());}
 [Fact]public async Task Discovered_relationship_requires_approved_fields_before_approval(){await using var configured=factory.WithWebHostBuilder(b=>b.ConfigureServices(s=>{s.RemoveAll<IExternalSchemaDiscoveryService>();s.AddScoped<IExternalSchemaDiscoveryService,FakeDiscovery>();}));using var client=await Admin(configured);var token=await Csrf(client);var created=await Post(client,"/api/admin/data-sources",new{name="Related ERP",secretKey="ERP_TEST",enabled=true},token);var id=(await created.Content.ReadFromJsonAsync<Created>())!.Id;var discovered=await Post(client,$"/api/admin/data-sources/{id}/discover",new{},token);Assert.Contains("FK_invoice_customer",await discovered.Content.ReadAsStringAsync());var relationship=new{name="Customer",description="Invoice customer",concepts="customer",relationshipType="ManyToOne",discoveredForeignKeyName="FK_invoice_customer",fromEntity="Invoices",fromField="CustomerCode",toEntity="Customers",toField="CustomerCode",enabled=true};Assert.Equal(HttpStatusCode.BadRequest,(await Post(client,$"/api/admin/data-sources/{id}/relationships",relationship,token)).StatusCode);await SaveMap(client,id,token,"erp_customer","Customers",("customer_code","CustomerCode"));await SaveMap(client,id,token,"erp_invoice","Invoices",("customer_ref","CustomerCode"));Assert.Equal(HttpStatusCode.OK,(await Post(client,$"/api/admin/data-sources/{id}/relationships",relationship,token)).StatusCode);var saved=await client.GetStringAsync($"/api/admin/data-sources/{id}/relationships");Assert.Contains("Customer",saved);Assert.Contains("FK_invoice_customer",saved);}
 [Fact]public async Task Scope_validation_persistence_entities_and_enabled_business_list_are_correct(){await using var configured=factory.WithWebHostBuilder(b=>b.ConfigureServices(s=>{s.RemoveAll<IExternalSchemaDiscoveryService>();s.AddScoped<IExternalSchemaDiscoveryService,FakeDiscovery>();}));using var client=await Admin(configured);var token=await Csrf(client);var created=await Post(client,"/api/admin/data-sources",new{name="Scoped ERP",secretKey="ERP_TEST",enabled=true},token);var id=(await created.Content.ReadFromJsonAsync<Created>())!.Id;await SaveMap(client,id,token,"erp_customer","Customers",("customer_code","CustomerCode"));var mappings=await client.GetFromJsonAsync<List<SavedMapping>>($"/api/admin/data-sources/{id}/mappings");var entityId=mappings!.Single(x=>x.BusinessEntityName=="Customers").Id;var empty=await Post(client,$"/api/admin/data-sources/{id}/scopes",new{name="",description="",enabled=true,entityIds=new[]{entityId}},token);Assert.Equal(HttpStatusCode.BadRequest,empty.StatusCode);Assert.Contains("Scope name is required",await empty.Content.ReadAsStringAsync());var noEntities=await Post(client,$"/api/admin/data-sources/{id}/scopes",new{name="Empty",description="",enabled=true,entityIds=Array.Empty<Guid>()},token);Assert.Equal(HttpStatusCode.BadRequest,noEntities.StatusCode);var valid=await Post(client,$"/api/admin/data-sources/{id}/scopes",new{name="Customer Intelligence",description="Customer data",enabled=true,entityIds=new[]{entityId}},token);Assert.Equal(HttpStatusCode.OK,valid.StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await Post(client,$"/api/admin/data-sources/{id}/scopes",new{name="Customer Intelligence",description="Duplicate",enabled=true,entityIds=new[]{entityId}},token)).StatusCode);var reloaded=await client.GetStringAsync($"/api/admin/data-sources/{id}/scopes");Assert.Contains("Customer Intelligence",reloaded);Assert.Contains("Customers",reloaded);var business=await client.GetStringAsync($"/api/data-sources/{id}/scopes");Assert.Contains("Customer Intelligence",business);Assert.Contains("Customers",business);using var other=await Admin(configured);Assert.Equal("[]",await other.GetStringAsync($"/api/admin/data-sources/{id}/scopes"));Assert.Equal("[]",await other.GetStringAsync($"/api/data-sources/{id}/scopes"));}
 [Fact]public async Task Anonymous_and_support_agent_cannot_configure_sources(){using var anonymous=factory.CreateClient(new WebApplicationFactoryClientOptions{HandleCookies=true});var token=await Csrf(anonymous);Assert.Equal(HttpStatusCode.Unauthorized,(await Post(anonymous,"/api/admin/data-sources",new{name="No",secretKey="NO",enabled=true},token)).StatusCode);using var support=await Admin();var me=await support.GetFromJsonAsync<User>("/api/auth/me");using(var scope=factory.Services.CreateScope()){var manager=scope.ServiceProvider.GetRequiredService<UserManager<ApplicationUser>>();var user=(await manager.FindByIdAsync(me!.Id.ToString()))!;await manager.RemoveFromRoleAsync(user,ApplicationRoles.Admin);await manager.AddToRoleAsync(user,ApplicationRoles.SupportAgent);}token=await Csrf(support);await Post(support,"/api/auth/logout",new{},token);token=await Csrf(support);await Post(support,"/api/auth/login",new{email=me.Email,password="ValidPassword123!"},token);token=await Csrf(support);Assert.Equal(HttpStatusCode.Forbidden,(await Post(support,"/api/admin/data-sources",new{name="No",secretKey="NO",enabled=true},token)).StatusCode);}
 async Task<HttpClient> Admin(WebApplicationFactory<Program>? app=null){var client=(app??factory).CreateClient(new WebApplicationFactoryClientOptions{HandleCookies=true});var token=await Csrf(client);var email=$"phase14-{Guid.NewGuid():N}@example.com";await Post(client,"/api/auth/register",new{organizationName="Phase 14",email,password="ValidPassword123!"},token);await Post(client,"/api/auth/login",new{email,password="ValidPassword123!"},token);return client;}
 static async Task<string> Csrf(HttpClient c)=>(await (await c.GetAsync("/api/auth/csrf")).Content.ReadFromJsonAsync<CsrfValue>())!.Token;
 static Task<HttpResponseMessage> Post(HttpClient c,string url,object body,string token){var r=new HttpRequestMessage(HttpMethod.Post,url){Content=JsonContent.Create(body)};r.Headers.Add("X-CSRF-TOKEN",token);return c.SendAsync(r);}
 static async Task SaveMap(HttpClient client,Guid id,string token,string table,string entity,(string Physical,string Logical) field){var mapping=new{schema="dbo",table,objectType="BASE TABLE",businessEntityName=entity,displayName=entity,description=entity,concepts=entity,enabled=true,fields=new[]{new{externalColumnName=field.Physical,businessFieldName=field.Logical,displayName=field.Logical,description=field.Logical,dataType="String",concepts=field.Logical,isQueryable=true,isSensitive=false}}};Assert.Equal(HttpStatusCode.OK,(await Post(client,$"/api/admin/data-sources/{id}/mappings",mapping,token)).StatusCode);}
 sealed record CsrfValue(string Token);sealed record Created(Guid Id);sealed record User(Guid Id,string Email);sealed record SavedMapping(Guid Id,string BusinessEntityName);
 sealed class FakeDiscovery:IExternalSchemaDiscoveryService{public Task<IReadOnlyList<ExternalDiscoveredObject>>DiscoverAsync(Guid id,CancellationToken token=default)=>Task.FromResult<IReadOnlyList<ExternalDiscoveredObject>>([new("dbo","erp_customer","BASE TABLE",[new("customer_code","nvarchar",false,true,true)]),new("dbo","erp_invoice","BASE TABLE",[new("customer_ref","nvarchar",false,false,true,true)],[new("FK_invoice_customer","dbo","erp_invoice","customer_ref","dbo","erp_customer","customer_code")])]);}
}
